using System.ComponentModel;

namespace MyNihongo.Mockurai;

/// <summary>
/// Generated by Mockurai for every <see cref="MockuraiExportAttribute"/>. Must not be used manually.
/// Maps the mocked type to the exported mock implementation, so that consuming assemblies can reuse it.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
[AttributeUsage(AttributeTargets.Assembly, AllowMultiple = true)]
public sealed class MockuraiExportedAttribute : Attribute
{
	/// <summary>
	/// Initializes a new instance of the <see cref="MockuraiExportedAttribute"/> class.
	/// </summary>
	/// <param name="type">The mocked type.</param>
	/// <param name="mockType">The exported mock implementation of <paramref name="type"/>.</param>
	public MockuraiExportedAttribute(Type type, Type mockType)
	{
		Type = type;
		MockType = mockType;
	}

	/// <summary>
	/// Gets the mocked type.
	/// </summary>
	public Type Type { get; }

	/// <summary>
	/// Gets the exported mock implementation.
	/// </summary>
	public Type MockType { get; }
}
